/* ---- JIT vtable schema (must match c_src/sparkle_jit.c) ---- */
typedef struct JitVTable {
    void* (*create)(void);
    void  (*destroy)(void* ctx);
    void  (*reset)(void* ctx);
    void  (*eval)(void* ctx);
    void  (*tick)(void* ctx);
    void  (*eval_tick)(void* ctx);
    void  (*set_input)(void* ctx, uint32_t idx, uint64_t val);
    uint64_t (*get_output)(void* ctx, uint32_t idx);
    uint64_t (*get_wire)(void* ctx, uint32_t idx);
    void  (*set_mem)(void* ctx, uint32_t mem_idx, uint32_t addr, uint32_t data);
    uint32_t (*get_mem)(void* ctx, uint32_t mem_idx, uint32_t addr);
    void  (*memset_word)(void* ctx, uint32_t mem_idx, uint32_t addr, uint32_t val, uint32_t count);
    const char* (*wire_name)(uint32_t idx);
    uint32_t (*num_wires)(void);
    void  (*set_reg)(void* ctx, uint32_t reg_idx, uint64_t val);
    uint64_t (*get_reg)(void* ctx, uint32_t reg_idx);
    const char* (*reg_name)(uint32_t idx);
    uint32_t (*num_regs)(void);
    void* (*snapshot)(void* ctx);
    void  (*restore)(void* ctx, void* snap);
    void  (*free_snapshot)(void* snap);
} JitVTable;

/* ---- Trampolines: void*-typed adapters for the vtable ---- */

static void* sparkle_jit_create(void) {
    struct sim* p = (struct sim*)calloc(1, sizeof(struct sim));
    if (p) sparkle_sim_reset(p);
    return (void*)p;
}

static void sparkle_jit_destroy(void* ctx) { free(ctx); }
static void sparkle_jit_reset(void* ctx) { sparkle_sim_reset((struct sim*)ctx); }
static void sparkle_jit_eval(void* ctx) { sparkle_sim_eval((struct sim*)ctx); }
static void sparkle_jit_tick(void* ctx) { sparkle_sim_tick((struct sim*)ctx); }
static void sparkle_jit_eval_tick(void* ctx) { sparkle_sim_eval_tick((struct sim*)ctx); }

static void sparkle_jit_set_input(void* ctx, uint32_t idx, uint64_t val) {
    struct sim* s = (struct sim*)ctx;
    switch (idx) {
        case 0: s->serial_sink_data = (uint8_t)val; break;
        case 1: s->serial_sink_valid = (uint8_t)val; break;
        case 2: s->serial_source_ready = (uint8_t)val; break;
        case 3: s->sys_clk = (uint8_t)val; break;
    }
}

static uint64_t sparkle_jit_get_output(void* ctx, uint32_t idx) {
    struct sim* s = (struct sim*)ctx;
    switch (idx) {
        case 0: return (uint64_t)s->serial_sink_ready;
        case 1: return (uint64_t)s->serial_source_data;
        case 2: return (uint64_t)s->serial_source_valid;
        case 3: return (uint64_t)s->sim_trace;
    }
    return 0;
}

