static void sparkle_jit_set_mem(void* ctx, uint32_t mem_idx, uint32_t addr, uint32_t data) {
    struct sim* s = (struct sim*)ctx; (void)s; (void)addr; (void)data;
    switch (mem_idx) {
        case 0: s->storage_1[addr] = data; break;
        case 1: s->storage[addr] = data; break;
        case 2: s->mem[addr] = data; break;
        case 3: s->main_ram[addr] = data; break;
        case 4: s->sram[addr] = data; break;
        case 5: s->rom[addr] = data; break;
        case 6: s->picorv32_cpuregs[addr] = data; break;
    }
}

static uint32_t sparkle_jit_get_mem(void* ctx, uint32_t mem_idx, uint32_t addr) {
    struct sim* s = (struct sim*)ctx; (void)s; (void)addr;
    switch (mem_idx) {
        case 0: return (uint32_t)s->storage_1[addr];
        case 1: return (uint32_t)s->storage[addr];
        case 2: return (uint32_t)s->mem[addr];
        case 3: return (uint32_t)s->main_ram[addr];
        case 4: return (uint32_t)s->sram[addr];
        case 5: return (uint32_t)s->rom[addr];
        case 6: return (uint32_t)s->picorv32_cpuregs[addr];
    }
    return 0;
}

static void sparkle_jit_memset_word(void* ctx, uint32_t mem_idx, uint32_t addr, uint32_t val, uint32_t count) {
    struct sim* s = (struct sim*)ctx; (void)s; (void)addr; (void)val; (void)count;
    switch (mem_idx) {
        case 0: for (uint32_t k = 0; k < count && (addr + k) < 16; k++) s->storage_1[addr + k] = val; break;
        case 1: for (uint32_t k = 0; k < count && (addr + k) < 16; k++) s->storage[addr + k] = val; break;
        case 2: for (uint32_t k = 0; k < count && (addr + k) < 64; k++) s->mem[addr + k] = val; break;
        case 3: for (uint32_t k = 0; k < count && (addr + k) < 16384; k++) s->main_ram[addr + k] = val; break;
        case 4: for (uint32_t k = 0; k < count && (addr + k) < 2048; k++) s->sram[addr + k] = val; break;
        case 5: for (uint32_t k = 0; k < count && (addr + k) < 32768; k++) s->rom[addr + k] = val; break;
        case 6: for (uint32_t k = 0; k < count && (addr + k) < 32; k++) s->picorv32_cpuregs[addr + k] = val; break;
    }
}

