static uint32_t sparkle_jit_num_regs(void) { return 187; }

static void* sparkle_jit_snapshot(void* ctx) {
    struct sim* p = (struct sim*)calloc(1, sizeof(struct sim));
    if (p) memcpy(p, ctx, sizeof(struct sim));
    return (void*)p;
}

static void sparkle_jit_restore(void* ctx, void* snap) {
    memcpy(ctx, snap, sizeof(struct sim));
}

static void sparkle_jit_free_snapshot(void* snap) { free(snap); }

